private com.android.systemui.hecker.HeckerBatteryDrawable mHeckerBattery;
private final Runnable mHeckerThemeListener = this::reloadHeckerBattery;
private final android.animation.ValueAnimator.DurationScaleChangeListener mHeckerMotionListener =
        scale -> post(this::syncHeckerBatteryAnimation);

@Override protected void onAttachedToWindow() {
    super.onAttachedToWindow();
    com.android.systemui.hecker.HeckerThemeAssets.addChangeListener(getContext(), mHeckerThemeListener);
    android.animation.ValueAnimator.registerDurationScaleChangeListener(mHeckerMotionListener);
    reloadHeckerBattery();
}
@Override protected void onDetachedFromWindow() {
    com.android.systemui.hecker.HeckerThemeAssets.removeChangeListener(mHeckerThemeListener);
    android.animation.ValueAnimator.unregisterDurationScaleChangeListener(mHeckerMotionListener);
    if (mHeckerBattery != null) mHeckerBattery.stop();
    super.onDetachedFromWindow();
}
@Override public void onVisibilityAggregated(boolean visible) {
    super.onVisibilityAggregated(visible);
    syncHeckerBatteryAnimation();
}
@Override public void onScreenStateChanged(int state) {
    super.onScreenStateChanged(state);
    syncHeckerBatteryAnimation();
}
@Override protected void onWindowVisibilityChanged(int visibility) {
    super.onWindowVisibilityChanged(visibility);
    syncHeckerBatteryAnimation();
}
private void syncHeckerBatteryAnimation() {
    if (mHeckerBattery == null) return;
    android.view.Display display = getDisplay();
    if (isAttachedToWindow() && isShown() && getWindowVisibility() == VISIBLE
            && mBatteryIconView != null && mBatteryIconView.isShown()
            && mBatteryIconView.getDrawable() == mHeckerBattery && display != null
            && display.getState() == android.view.Display.STATE_ON) mHeckerBattery.start();
    else mHeckerBattery.stop();
}
private void reloadHeckerBattery() {
    if (mHeckerBattery != null) mHeckerBattery.stop();
    mHeckerBattery = com.android.systemui.hecker.HeckerBatteryDrawable.create(getContext());
    scaleBatteryMeterViews();
    updateHeckerBattery();
}
private void updateHeckerBattery() {
    if (mBatteryIconView == null) { if (mHeckerBattery != null) mHeckerBattery.stop(); return; }
    if (mHeckerBattery == null || mBatteryStateUnknown || mIsBatteryDefender || mIsIncompatibleCharging) {
        if (mHeckerBattery != null) mHeckerBattery.stop();
        mBatteryIconView.setImageDrawable(mBatteryStateUnknown ? getUnknownStateDrawable()
                : NewStatusBarIcons.isEnabled() ? mUnifiedBattery : mDrawable);
        return;
    }
    boolean percent = NewStatusBarIcons.isEnabled() ? mUnifiedBatteryState.getShowPercent()
            : mBatteryPercentView != null;
    mHeckerBattery.update(mLevel, isCharging(), mPowerSaveEnabled, percent, mTextColor);
    if (mBatteryIconView.getDrawable() != mHeckerBattery) mBatteryIconView.setImageDrawable(mHeckerBattery);
    syncHeckerBatteryAnimation();
    android.view.ViewGroup.LayoutParams params = mBatteryIconView.getLayoutParams();
    int width = Math.round(params.height * mHeckerBattery.getIntrinsicWidth()
            / (float) mHeckerBattery.getIntrinsicHeight());
    if (params.width != width) { params.width = width; mBatteryIconView.setLayoutParams(params); }
}

private final AccessorizedBatteryDrawable mDrawable;

